function currentTaskBadge(t){return t.done?badge('Concluído',''):t.date<TODAY?badge('Prazo vencido','amber'):t.date===TODAY?badge('Hoje','blue'):badge(datestr(t.date),'neutral');}
function taskRows(tasks){return tasks.length?tasks.map(t=>`<div class="task-row ${t.done?'done':''}"><button type="button" class="task-check" data-action="task-toggle" data-id="${esc(t.id)}" aria-label="${t.done?'Reabrir':'Concluir'}: ${esc(t.title)}" aria-pressed="${t.done}">${t.done?icon('check'):''}</button><div class="task-detail"><strong>${esc(t.title)}</strong><small>${esc(caseBy(t.caseId).name)} · ${esc(t.owner)}</small></div>${currentTaskBadge(t)}</div>`).join(''):empty('Tudo acompanhado por aqui','Quando houver um próximo passo, ele aparecerá nesta lista.');}
function eventRows(events){return events.length?events.map(e=>`<button type="button" class="agenda-item" data-action="event" data-id="${esc(e.id)}"><span class="agenda-time">${esc(e.time)}</span><span class="agenda-dot ${esc(e.color)}"></span><span><strong>${esc(e.title)}</strong><small>${esc(caseBy(e.caseId).name)}</small><small>${esc(e.location)}${e.status!=='Agendado'?' · '+esc(e.status):''}</small></span></button>`).join(''):empty('Sem compromissos neste dia','Consulte a semana para ver os próximos encontros.');}
function caseRows(cases){return cases.map(c=>`<button type="button" class="case-row" data-action="case" data-id="${esc(c.id)}">${avatar(c.initials,c.color)}<span class="case-info"><strong>${esc(c.name)}</strong><small>${esc(c.context)}</small></span><span class="case-meta">${badge(c.status,c.statusKind)}<small>${esc(c.last)}</small></span><span class="case-chevron">${icon('arrow')}</span></button>`).join('');}
function network(c){return `<div class="care-network"><svg viewBox="0 0 390 238" role="img" aria-label="${esc(c.name)} no centro da rede formada por Edilaine, família, psicologia e rotina"><path d="M85 62C136 56 117 106 194 115M317 53C274 52 280 99 194 115M79 182C128 194 128 149 194 115M313 178C263 196 262 140 194 115" stroke="#b1bf95" stroke-width="1.3" fill="none"/><circle cx="194" cy="115" r="54" fill="none" stroke="#d2dcc1"/><circle cx="194" cy="115" r="43" fill="#fff"/><circle cx="194" cy="111" r="29" fill="#e5ebd8"/><text x="194" y="117" text-anchor="middle" fill="#475436" font-size="17" font-weight="600">${esc(c.initials)}</text><text x="194" y="177" text-anchor="middle" fill="#475436" font-size="13" font-weight="600">${esc(c.name.split(' ')[0])}</text><text x="194" y="195" text-anchor="middle" fill="#72786b" font-size="9">No centro do cuidado</text><circle cx="85" cy="62" r="21" fill="#fff"/><text x="85" y="66" text-anchor="middle" fill="#475436" font-size="11" font-weight="600">EF</text><text x="85" y="99" text-anchor="middle" fill="#59634e" font-size="10">Edilaine</text><circle cx="317" cy="53" r="21" fill="#e1ebf0"/><text x="317" y="57" text-anchor="middle" fill="#4d6879" font-size="11" font-weight="600">ML</text><text x="317" y="89" text-anchor="middle" fill="#59634e" font-size="10">Psicologia</text><circle cx="79" cy="182" r="21" fill="#f1e1cd"/><text x="79" y="186" text-anchor="middle" fill="#6f604b" font-size="11" font-weight="600">CD</text><text x="79" y="218" text-anchor="middle" fill="#59634e" font-size="10">Família</text><circle cx="313" cy="178" r="21" fill="#fff"/><path d="M305 185c0-12 5-17 16-16-1 12-6 17-16 16Zm0 4 12-16" fill="none" stroke="#879257" stroke-width="1.2"/><text x="313" y="214" text-anchor="middle" fill="#59634e" font-size="10">Rotina</text><circle cx="123" cy="72" r="3" fill="#879257"/><circle cx="274" cy="70" r="3" fill="#879257"/></svg></div>`;}
function heading(title,description='',action='',date=''){return `<div class="page-heading"><div>${date?`<div class="date-caption">${esc(date)}</div>`:''}<h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${action}</div>`;}
function summaryCard(c,personal=false){const manager=state.role==='manager';return `<div class="summary-panel"><div class="summary-head">${icon('leaf')}<span>${personal?'Combinados do acompanhamento':manager?'Síntese da coordenação · '+(c.summaryReviewed?'atualizada na demonstração':'5 out'):'Síntese compartilhada com a equipe · 5 out'}</span></div><h2>${personal?'Pequenos passos, no seu ritmo.':'O que importa neste momento'}</h2><p style="white-space:pre-line">${esc(personal?c.familySummary:manager?(c.coordinationSummary||c.summary):c.summary)}</p>${!personal&&manager?`<div class="row wrap" style="margin-top:16px">${!c.summaryReviewed&&recordsFor(c.id).some(r=>r.date>='2026-10-06')?badge('Novos registros desde a revisão','amber'):''}${btn('Preparar revisão','prepare-summary',`data-case="${c.id}"`,'small','book')}</div>`:''}<div class="summary-details"><div><small>O que ${esc(c.name.split(' ')[0])} deseja</small><p>${esc(c.preference)}</p></div><div><small>Próxima revisão</small><p>${esc(c.review)} · Com Edilaine e a equipe</p></div></div></div>`;}
function goalsHtml(id,editable=false){const goals=data.goals.filter(g=>g.caseId===id);return goals.map(g=>`<div class="goal-item"><div class="row spread"><h3>${esc(g.title)}</h3>${badge(g.status,g.status==='Atingido'?'':g.status==='Revisar'?'amber':'neutral')}</div><div class="goal-bar" aria-label="Progresso ilustrativo do combinado: ${g.progress}%"><span style="width:${g.progress}%"></span></div><div class="row spread"><small>${esc(g.owner)}</small><small>Revisão: ${datestr(g.review)}</small></div><p class="goal-note">${esc(g.note)}</p>${editable?btn('Revisar objetivo','goal',`data-id="${g.id}"`,'text','edit'):''}</div>`).join('')||empty('Plano em preparação','Os objetivos serão combinados com a pessoa acompanhada.');}
function dashboard(){
 const role=state.role,p=profiles[role],c=getCase(),todayEvents=eventsFor().filter(e=>e.date===TODAY);
 const pending=tasksFor().filter(t=>!t.done).slice(0,3);
 if(role==='manager')return `${heading('Bom dia, Edilaine.','Um olhar atento para o que mudou e para o que vem a seguir.',btn('Registrar','compose','','primary','plus'),'Terça-feira, 6 de outubro de 2026')}<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><span class="hero-pill">${icon('book')}Novo relato da família</span><h2 id="hero-title">Helena retomou<br>sua caminhada.</h2><p>Cláudia compartilhou uma conquista nesta manhã. Um momento da rotina que pode orientar os próximos passos.</p>${btn('Ler o relato','case','data-id="helena" data-tab="diario"','primary','book')}</div>${network(caseBy('helena'))}</section><div class="dashboard-columns"><div><section><div class="section-header"><h2>Pessoas que você acompanha</h2>${btn('Ver todos os casos','nav','data-view="casos"','text')}</div><div class="case-list">${caseRows(allowedCases())}</div><p class="fine-print">Os sinais indicam atualização e pendências de coordenação, não condição clínica.</p></section><section class="section-gap panel"><div class="section-header"><h2>Próximos passos</h2>${btn('Ver todos','nav','data-view="tarefas"','text')}</div>${taskRows(pending)}</section></div><aside class="right-column"><section class="panel"><div class="section-header"><h2>Hoje, na agenda</h2>${badge('6 out','neutral')}</div>${eventRows(todayEvents)}<div class="section-gap">${btn('Abrir a semana','nav','data-view="agenda"','text','calendar')}</div></section><section class="panel"><div class="section-header"><h2>O cuidado em movimento</h2></div><div class="activity-line"><span class="activity-dot"></span><div>Cláudia registrou uma caminhada com Helena.<br><small>Hoje, às 08:35</small></div></div><div class="activity-line"><span class="activity-dot"></span><div>Marina compartilhou a síntese do encontro.<br><small>Ontem, às 16:40</small></div></div><div class="activity-line"><span class="activity-dot"></span><div>O plano de Beatriz foi revisado.<br><small>Ontem, às 09:30</small></div></div></section></aside></div>`;
 if(role==='professional')return `${heading('Bom dia, Marina.','Seu olhar se conecta ao cuidado de toda a equipe.',btn('Registrar evolução','compose','','primary','plus'),'Terça-feira, 6 de outubro de 2026')}<section class="profile-hero"><div><div class="profile-subtitle">Seu próximo encontro</div><h2>Helena, às 09:00.</h2><p>Consulte os combinados da equipe e os objetivos antes do encontro. Depois, compartilhe apenas a síntese necessária à coordenação.</p>${btn('Preparar o encontro','case','data-id="helena"','primary','book')}</div><div class="hero-art">${network(caseBy('helena'))}</div></section><div class="dashboard-columns"><div><div class="section-header"><h2>Seus casos</h2>${badge('2 casos atribuídos','neutral')}</div><div class="case-list">${caseRows(allowedCases())}</div><section class="section-gap panel"><div class="section-header"><h2>Suas próximas ações</h2></div>${taskRows(pending)}</section><div class="private-note"><div class="row">${icon('lock')}<h3>Seu espaço profissional</h3></div><p>Esta visão demonstra a síntese compartilhada. Notas clínicas restritas não aparecem para familiares ou para a coordenação.</p></div></div><aside><section class="panel"><div class="section-header"><h2>Seus encontros de hoje</h2></div>${eventRows(todayEvents)}</section><section class="panel"><h3>Uma síntese que ajuda</h3><p class="goal-note">O que foi feito, o que a equipe precisa saber e qual é o próximo passo. Você confere a audiência antes de publicar.</p>${btn('Abrir modelo de evolução','compose','','text','edit')}</section></aside></div>`;
 const isPatient=role==='patient';
 return `${heading(isPatient?'Bom dia, Helena.':'Bom dia, Cláudia.',isPatient?'Seus objetivos e combinados, com espaço para a sua voz.':'Você também faz parte da rede de cuidado.',btn('Registrar acontecimento','compose','','primary','plus'),'Terça-feira, 6 de outubro de 2026')}<section class="profile-hero"><div><div class="profile-subtitle">Acompanhamento de Helena</div><h2>${isPatient?'Como você está vivendo seu dia?':'Como foi o dia da Helena?'}</h2><p>${isPatient?'Uma conquista, uma dificuldade ou algo que você gostaria de conversar. Seu relato chega à coordenação do cuidado.':'Uma caminhada, uma mudança na rotina, uma dúvida. Compartilhe o que aconteceu, por texto ou com um áudio de exemplo.'}</p><div class="row wrap">${btn('Escrever um relato','compose','','primary','edit')}${btn('Experimentar o áudio','compose','data-mode="audio"','soft','mic')}</div></div><div class="hero-art">${network(c)}</div></section><div class="two-col"><div>${summaryCard(c,true)}<section class="section-gap"><div class="section-header"><h2>${isPatient?'Seu diário':'Seus registros'}</h2>${btn('Ver o diário','nav','data-view="diario"','text')}</div>${timelineCards(recordsFor(c.id).slice(0,2))}</section></div><aside><section class="panel"><div class="section-header"><h2>Os próximos encontros</h2></div>${eventRows(eventsFor(c.id).filter(e=>e.date>=TODAY).slice(0,3))}</section><section class="panel"><div class="section-header"><h2>Combinados da semana</h2></div><p class="goal-note">Apoiar escolhas possíveis para a rotina, registrar o que ajudou e levar as dúvidas à próxima revisão.</p>${btn('Ler orientações','nav','data-view="orientacoes"','text','leaf')}</section></aside></div><div class="bottom-note">${icon('lock')}Esta visão mostra apenas os registros e conteúdos disponibilizados para ${isPatient?'você':'a família'}.</div>${isPatient?'<div class="fine-print">Participação direta do paciente: proposta para validar com Edilaine.</div>':''}`;
}
const dashboardBase=dashboard;
dashboard=function(){
 const p=profiles[state.role];
 const internal=['manager','professional'].includes(state.role);
 const workspace=`<div class="bottom-note workspace-status">${icon(internal?'cloud':'lock')}<span><strong>${internal?'Conta Google Workspace da Francescato':'Acesso convidado ao acompanhamento'}</strong> · ${esc(p.name)} · acesso individual e permissões por caso</span></div>`;
 const content=dashboardBase();
 return content.includes('<section class="hero"')?content.replace('<section class="hero"',`${workspace}<section class="hero"`):content.replace('<section class="profile-hero"',`${workspace}<section class="profile-hero"`);
};
function caseTiles(cases){return cases.map(c=>`<button type="button" class="case-tile" data-action="case" data-id="${c.id}"><div class="row spread"><div class="row">${avatar(c.initials,c.color)}<div><h3>${esc(c.name)}</h3><small class="muted">${c.age} anos</small></div></div>${badge(c.status,c.statusKind)}</div><p>${esc(c.change)}</p><div class="case-tile-footer"><div class="avatar-stack">${c.professionals.slice(0,3).map(id=>{const t=team.find(x=>x.id===id);return avatar(t.initials,t.color,'tiny');}).join('')}</div><small>Revisão: ${esc(c.review)}</small><span>${icon('arrow')}</span></div></button>`).join('')||empty('Nenhum caso encontrado','Experimente buscar outro nome ou alterar o filtro.');}
function filteredCases(){return allowedCases().filter(c=>(state.caseFilter==='Todos'||(state.caseFilter==='Acompanhar'?c.statusKind==='amber':c.statusKind!== 'amber'))&&c.name.toLocaleLowerCase('pt-BR').includes(state.caseSearch.toLocaleLowerCase('pt-BR')));}
function casesPage(){return `${heading('Pessoas acompanhadas','Uma visão da rotina, dos combinados e do que merece atenção.',state.role==='manager'?btn('Novo caso','new-case','','primary','plus'):'')}<div class="toolbar"><div class="chips">${['Todos','Acompanhar','Em dia e revisão'].map(v=>`<button class="chip ${v===state.caseFilter?'active':''}" data-action="case-filter" data-filter="${v}">${v}</button>`).join('')}</div><label class="sr-only" for="case-search">Buscar pessoa acompanhada</label><input id="case-search" class="input-search" placeholder="Buscar pelo nome…" value="${esc(state.caseSearch)}"></div><div id="case-grid" class="case-grid">${caseTiles(filteredCases())}</div><p class="fine-print">Todos os casos desta apresentação são fictícios.</p>`;}
function timelineCards(records){return records.length?`<div class="timeline">${records.map(r=>`<article class="timeline-card ${r.request&&r.status==='Aguardando retorno'?'highlight':''}"><header>${avatar(r.initials,profiles[r.role]?.color||'')}<div><strong>${esc(r.author)}</strong><small>${datestr(r.date)} às ${esc(r.time)} · ${esc(r.category)}</small></div>${badge(r.status,r.status==='Aguardando retorno'?'amber':'neutral')}</header><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p>${r.context?`<p class="goal-note"><strong>Contexto:</strong> ${esc(r.context)}</p>`:''}${r.attachment?`<button type="button" class="button small section-gap" data-action="attachment" data-id="${r.id}">${icon('image')}${r.attachment==='exemplo'?'Imagem da caminhada':esc(r.attachment.name||r.attachment)}</button>`:''}${r.reply?`<div class="info-box" style="margin-top:15px;margin-bottom:0"><span>${icon('chat')}</span><div><strong>Retorno de Edilaine</strong><br>${esc(r.reply)}</div></div>`:''}<footer><span class="audience">${icon('lock')}${esc(audienceLabel(r.audience))}</span>${state.role==='manager'?`<span style="margin-left:auto" class="row wrap">${btn('Dar retorno','reply',`data-id="${r.id}"`,'text','chat')}${!r.audience.includes('professional')?btn('Compartilhar com equipe','share-record',`data-id="${r.id}"`,'text','share'):''}${btn('Criar próximo passo','record-task',`data-id="${r.id}"`,'text','plus')}</span>`:''}</footer></article>`).join('')}</div>`:empty('O diário começa com o primeiro relato','Registre um acontecimento ou uma síntese para dar continuidade ao cuidado.',btn('Registrar','compose','','primary','plus'));}
function audienceLabel(a){if(a.includes('family')&&a.includes('patient')&&a.includes('professional'))return 'Equipe, paciente e família autorizados';if(a.includes('family')&&a.includes('professional'))return 'Equipe e família autorizada';if(a.includes('family'))return 'Coordenação e familiar autor';if(a.includes('patient'))return 'Coordenação e paciente';return 'Equipe do caso';}
function diaryPage(c){const rows=recordsFor(c.id).filter(r=>state.diaryFilter==='Todos'||(state.diaryFilter==='Família'?r.role==='family':state.diaryFilter==='Equipe'?['manager','professional'].includes(r.role):r.author===profiles[state.role].name));const filters=state.role==='manager'?['Todos','Família','Equipe']:['Todos','Meus registros'];return `<div class="toolbar"><div class="chips">${filters.map(f=>`<button class="chip ${f===state.diaryFilter?'active':''}" data-action="diary-filter" data-filter="${f}">${f}</button>`).join('')}</div>${btn('Registrar','compose','','primary','plus')}</div>${['family','patient'].includes(state.role)?`<div class="info-box">${icon('lock')}<span>Você vê seus relatos e as informações compartilhadas com você. Registros internos da equipe ficam na visão profissional.</span></div>`:''}<div class="two-col"><div>${timelineCards(rows)}</div><aside><section class="panel"><h2>Um relato útil</h2><div class="facts section-gap"><div class="fact"><small>Quando aconteceu?</small><p>Data e momento do dia.</p></div><div class="fact"><small>O que mudou?</small><p>Descreva o acontecimento, sem precisar interpretá-lo.</p></div><div class="fact"><small>O que ajudou?</small><p>Contexto, ação tomada ou dificuldade encontrada.</p></div></div></section><section class="panel"><h3>Precisa de contato imediato?</h3><p class="goal-note">O diário não garante resposta imediata. Consulte os canais e horários acordados com a equipe.</p>${btn('Ver canais e orientações','case-tab','data-tab="orientacoes"','text','info')}</section></aside></div>`;}
function casePage(){const c=getCase(),personal=['family','patient'].includes(state.role),tabs=personal?['resumo','diario','plano','agenda','orientacoes','documentos']:['resumo','diario','plano','agenda','equipe','documentos','anamnese','orientacoes'];if(!tabs.includes(state.tab))state.tab='resumo';const labels={resumo:'Visão do caso',diario:'Diário',plano:'Plano de cuidado',agenda:'Agenda',equipe:'Rede de cuidado',documentos:'Documentos',anamnese:'Anamnese',orientacoes:'Orientações'};let body='';
 if(state.tab==='resumo')body=`<div class="two-col"><div>${summaryCard(c,personal)}<section class="panel section-gap"><div class="section-header"><h2>Objetivos em movimento</h2>${btn('Ver plano','case-tab','data-tab="plano"','text')}</div>${goalsHtml(c.id).split('<div class="goal-item">').slice(0,3).join('<div class="goal-item">')}</section><section class="section-gap"><div class="section-header"><h2>Últimos registros</h2>${btn('Abrir diário','case-tab','data-tab="diario"','text')}</div>${timelineCards(recordsFor(c.id).slice(0,2))}</section></div><aside><section class="panel"><h2>Sobre ${esc(c.name.split(' ')[0])}</h2><div class="facts section-gap"><div class="fact"><small>O que gosta e valoriza</small><p>${esc(c.strength)}</p></div><div class="fact"><small>O que tem dificultado</small><p>${esc(c.barrier)}</p></div><div class="fact"><small>Coordenação</small><div class="contact-person">${avatar('EF')}<div><strong>Edilaine Francescato</strong><small>Case manager</small></div></div></div></div></section><section class="panel"><div class="section-header"><h2>Próximos encontros</h2></div>${eventRows(eventsFor(c.id).filter(e=>e.date>=TODAY).slice(0,2))}</section>${!personal?`<section class="panel"><h2>Próximos passos</h2>${taskRows(tasksFor(c.id).filter(t=>!t.done).slice(0,3))}</section>`:''}</aside></div>`;
 if(state.tab==='diario')body=diaryPage(c);
 if(state.tab==='plano')body=`<div class="two-col"><section class="panel"><div class="section-header"><h2>Escolhas que viram objetivos</h2>${state.role==='manager'?btn('Adicionar objetivo','new-goal','','small','plus'):''}</div>${goalsHtml(c.id,state.role==='manager')}<p class="fine-print">As barras ilustram o acompanhamento dos combinados. Não representam uma avaliação clínica.</p></section><aside><section class="panel"><h2>Revisão do plano</h2><p class="goal-note">A perspectiva de ${esc(c.name.split(' ')[0])}, as observações da equipe e os acontecimentos da rotina orientam os ajustes.</p><div class="facts section-gap"><div class="fact"><small>Próxima revisão</small><p>${esc(c.review)}</p></div><div class="fact"><small>O que a pessoa deseja</small><p>${esc(c.preference)}</p></div></div></section><section class="panel"><h3>Histórico dos combinados</h3><p class="goal-note">5 out · Plano da semana compartilhado.<br>2 out · Objetivos escolhidos com a equipe.<br>29 set · Prioridades de rotina identificadas.</p></section></aside></div>`;
 if(state.tab==='agenda')body=agendaPage(c.id,true);
 if(state.tab==='equipe')body=teamPage(c.id,true);
 if(state.tab==='documentos')body=documentsPage(c.id,true);
 if(state.tab==='anamnese')body=anamnesePage(c);
 if(state.tab==='orientacoes')body=orientationsPage(true);
 return `${!personal?`<button class="back-link" data-action="nav" data-view="casos">${icon('back')}Pessoas acompanhadas</button>`:''}<div class="case-top">${avatar(c.initials,c.color,'big')}<div><h1>${esc(c.name)}</h1><p>${c.age} anos · ${esc(c.context)}</p></div><div class="case-top-actions">${!personal?badge(c.status,c.statusKind):badge('Acompanhamento ativo')}${btn(state.role==='professional'?'Registrar evolução':'Registrar','compose','','primary','plus')}</div></div><nav class="tabs" aria-label="Seções do caso">${tabs.map(t=>`<button type="button" class="tab ${state.tab===t?'active':''}" data-action="case-tab" data-tab="${t}" aria-current="${state.tab===t?'page':'false'}">${labels[t]}</button>`).join('')}</nav>${body}`;
}

function weekDates(){const mon=new Date('2026-10-05T12:00:00');mon.setDate(mon.getDate()+state.week*7);return Array.from({length:5},(_,i)=>{const d=new Date(mon);d.setDate(mon.getDate()+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;});}
function agendaPage(caseId=null,inside=false){const dates=weekDates(),events=eventsFor(caseId),weekEvents=events.filter(e=>dates.includes(e.date));const days=['Segunda','Terça','Quarta','Quinta','Sexta'];
 const title=datestr(dates[0],{day:'numeric',month:'long'})+' a '+datestr(dates[4],{day:'numeric',month:'long'});
 const controls=`<div class="row"><button type="button" class="icon-button" data-action="week-prev" aria-label="Semana anterior">${icon('back')}</button>${btn('Semana de exemplo','week-reset','','small')}<button type="button" class="icon-button" data-action="week-next" aria-label="Próxima semana">${icon('arrow')}</button></div>`;
 const calendar=state.agendaMode==='semana'?`<div class="week-scroll"><div class="week-grid"><div class="week-head">Horários</div>${dates.map((d,i)=>`<div class="week-head ${d===TODAY?'today':''}">${days[i]}<strong>${Number(d.slice(8))}</strong></div>`).join('')}<div class="time-column">${Array.from({length:9},(_,i)=>`<span>${String(i+8).padStart(2,'0')}:00</span>`).join('')}</div>${dates.map(d=>`<div class="day-column">${weekEvents.filter(e=>e.date===d).map(e=>{const [h,m]=e.time.split(':').map(Number);const top=(h-8+m/60)*76;return `<button type="button" class="calendar-event ${esc(e.color)}" style="top:${top}px;height:${Math.max(58,e.duration/60*76-6)}px" data-action="event" data-id="${e.id}"><small>${esc(e.time)} · ${e.duration} min</small><strong>${esc(caseBy(e.caseId).name.split(' ')[0])}</strong><small>${esc(e.area)}</small></button>`;}).join('')}</div>`).join('')}</div></div>`:`<section class="panel">${dates.map((d,i)=>`<div class="agenda-list-day">${days[i]}, ${datestr(d)}</div>${eventRows(weekEvents.filter(e=>e.date===d))}`).join('')}</section>`;
 return `${!inside?heading('Agenda do cuidado','Compromissos, pessoas e combinados em uma mesma semana.',['manager','professional'].includes(state.role)?btn('Novo compromisso','new-event',caseId?`data-case="${caseId}"`:'','primary','plus'):''):''}<div class="week-toolbar"><div><h2>${esc(title)}</h2><small class="muted">${caseId?'Agenda de '+esc(caseBy(caseId).name):'Compromissos autorizados para este perfil'}</small></div>${controls}</div><div class="toolbar"><div class="chips">${['semana','lista'].map(m=>`<button type="button" class="chip ${state.agendaMode===m?'active':''}" data-action="agenda-mode" data-mode="${m}">${m==='semana'?'Semana':'Lista'}</button>`).join('')}</div>${inside&&['manager','professional'].includes(state.role)?btn('Novo compromisso','new-event',`data-case="${caseId}"`,'small','plus'):''}</div>${calendar}<div class="bottom-note">${icon('calendar')}Clique em um compromisso para ver os detalhes${['manager','professional'].includes(state.role)?' e registrar a realização':''}.</div>`;
}
const agendaPageBase=agendaPage;
agendaPage=function(caseId=null,inside=false){
 const integration=`<div class="info-box google-integration">${icon('cloud')}<span><strong>Google Agenda da Francescato</strong><br>Visão consolidada da agenda geral e dos calendários autorizados. Última atualização demonstrativa: agora.</span>${['manager','professional'].includes(state.role)?btn('Atualizar','calendar-sync','','small','refresh'):''}</div>`;
 return agendaPageBase(caseId,inside).replace('<div class="week-toolbar">',`${integration}<div class="week-toolbar">`);
};
function tasksPage(){let tasks=tasksFor();tasks=tasks.filter(t=>state.taskFilter==='Todos'||(state.taskFilter==='Concluídos'?t.done:!t.done));return `${heading('Próximos passos','Cada combinado com uma pessoa responsável e um momento para agir.',btn('Adicionar próximo passo','new-task','','primary','plus'))}<div class="toolbar"><div class="chips">${['Pendentes','Concluídos','Todos'].map(f=>`<button type="button" class="chip ${f===state.taskFilter?'active':''}" data-action="task-filter" data-filter="${f}">${f}</button>`).join('')}</div></div><div class="two-col"><section class="panel">${taskRows(tasks)}</section><aside><section class="panel"><h2>Coordenação que continua</h2><p class="goal-note">Um acontecimento pode gerar uma ação. Ao concluir o combinado, o histórico continua acessível e a pessoa responsável fica identificada.</p><div class="facts section-gap"><div class="fact"><small>Responsável</small><p>${state.role==='professional'?'Marina Lima':'Edilaine e equipe atribuída'}</p></div><div class="fact"><small>Origem</small><p>Relato, revisão, reunião ou iniciativa da equipe.</p></div></div></section></aside></div>`;}
function teamPage(caseId=null,inside=false){const ids=caseId?caseBy(caseId).professionals:null;const people=team.filter(t=>!ids||ids.includes(t.id)||t.id==='edilaine');return `${!inside?heading('Uma rede em torno de cada pessoa','Profissionais conectados por objetivos e combinados de cuidado.'):''}<div class="team-grid">${people.map(p=>`<section class="team-card">${avatar(p.initials,p.color,'big')}<h3>${esc(p.name)}</h3><p>${esc(p.area)}</p>${badge(p.id==='edilaine'?'Coordenação':'Profissional vinculado','neutral')}<footer>${esc(p.frequency)}<br>${esc(p.responsibility)}</footer>${btn('Ver participação','team-detail',`data-id="${p.id}"${caseId?` data-case="${caseId}"`:''}`,'text','people')}</section>`).join('')}</div><div class="bottom-note">${icon('lock')}O vínculo com a equipe não libera automaticamente todos os casos ou todos os registros.</div>`;}
function documentsPage(caseId=null,inside=false){
 const docs=accessible(data.documents).filter(d=>(!caseId||d.caseId===caseId)&&(state.docProvider==='Todos'||d.provider===state.docProvider));
 return `${!inside?heading('Anexos e documentos','Arquivos classificados por pessoa, em um espaço institucional único.'):''}
 <div class="info-box">${icon('cloud')}<span><strong>Google Drive da Francescato conectado</strong><br>Todo anexo fica vinculado ao caso, à categoria e à audiência definida. Nesta demonstração, nenhum arquivo é enviado de verdade.</span></div>
 <div class="toolbar"><div class="chips">${['Todos','Google Drive'].map(p=>`<button type="button" class="chip ${state.docProvider===p?'active':''}" data-action="doc-provider" data-provider="${p}">${p}</button>`).join('')}</div>${['manager','professional'].includes(state.role)?btn('Adicionar anexo','new-doc',caseId?`data-case="${caseId}"`:'','small','plus'):''}</div>
 <div class="documents">${docs.map(d=>`<article class="document-row"><span class="doc-icon">${icon('file')}</span><div class="document-detail"><strong>${esc(d.name)}</strong><small>${esc(caseBy(d.caseId).name)} · ${esc(d.type)} · ${datestr(d.date)}</small><br><small>Google Drive da Francescato · pasta do caso</small></div>${badge(state.role==='manager'?audienceLabel(d.audience):'Disponibilizado para você','neutral')}${btn('Ver anexo','document',`data-id="${d.id}"`,'small')}</article>`).join('')||empty('Nenhum anexo nesta seleção','Altere o filtro ou inclua o primeiro anexo do caso.')}</div>`;
}
function anamnesePage(c){const saved=data.anamneses[c.id]||{};const value=(key,fallback)=>esc(saved[key]??fallback);return `<div class="two-col"><section class="panel"><div class="section-header"><h2>Conhecer a pessoa, além do caso</h2>${badge(saved.saved?'Atualizado na demonstração':'Preenchimento inicial','neutral')}</div><p class="goal-note">O contexto pode ser preenchido aos poucos. Avaliações e diagnósticos documentados mantêm sua origem profissional.</p><form data-form="anamnese" data-case="${c.id}"><fieldset style="border:0;padding:0;margin:0" ${state.role!=='manager'?'disabled':''}><div class="form-section"><h3>Prioridades e rotina</h3><div class="form-grid"><div class="field full"><label for="anam-reason">O que motivou o acompanhamento?</label><textarea id="anam-reason" name="reason">${value('reason','Apoiar a organização da rotina e a continuidade dos combinados de cuidado.')}</textarea></div><div class="field full"><label for="anam-preference">O que a pessoa considera importante?</label><input id="anam-preference" name="preference" value="${value('preference',c.preference)}"></div><div class="field"><label for="anam-strength">Pontos fortes e interesses</label><textarea id="anam-strength" name="strength">${value('strength',c.strength)}</textarea></div><div class="field"><label for="anam-barrier">Barreiras e necessidades de apoio</label><textarea id="anam-barrier" name="barrier">${value('barrier',c.barrier)}</textarea></div></div></div><div class="form-section"><h3>Rede e contexto</h3><div class="form-grid"><div class="field"><label for="anam-network">Familiar / cuidador de referência</label><input id="anam-network" name="network" value="${value('network',c.family)}"></div><div class="field"><label for="anam-source">Origem das informações</label><select id="anam-source" name="source"><option ${saved.source==='Pessoa e família'?'selected':''}>Pessoa e família</option><option ${saved.source==='Equipe profissional'?'selected':''}>Equipe profissional</option><option ${saved.source==='Ainda não confirmado'?'selected':''}>Ainda não confirmado</option></select></div></div><details><summary>Saúde e tratamentos documentados — a complementar</summary><p>Modelo de organização: informação, origem, data e situação de confirmação. Os campos clínicos serão validados pelos profissionais; este mockup não reúne diagnóstico ou prescrição.</p></details></div>${state.role==='manager'?`<div class="form-footer"><small class="muted">Informações de exemplo, guardadas apenas neste navegador.</small><button class="button primary" type="submit">${icon('check')}Salvar contexto</button></div>`:''}</fieldset></form></section><aside><section class="panel"><h2>Um bom ponto de partida</h2><p class="goal-note">O que a pessoa deseja, quem participa e quais apoios já existem. Não é necessário ter todas as respostas no primeiro encontro.</p><div class="contact-person section-gap">${avatar('EF')}<div><strong>Edilaine Francescato</strong><small>Responsável pela coordenação</small></div></div></section><section class="panel"><h3>Fonte e confirmação</h3><p class="goal-note">Relato familiar, informação documentada e avaliação profissional são identificados separadamente.</p></section></aside></div>`;}
function orientationsPage(inside=false){return `${!inside?heading('Orientações e combinados','Um lugar para encontrar o que foi acordado para o acompanhamento.'):''}<section class="orientation-card">${badge('Compartilhado com Helena e família','neutral','leaf')}<h2>Pequenos passos na rotina</h2><p>Como exemplo de apresentação, o espaço reúne os combinados escolhidos com a equipe: atividades de preferência, o que ajudou e questões a conversar no próximo encontro.</p><p>Uma conquista ou dificuldade pode ser registrada no diário. O relato mantém a voz de quem o escreveu e pode orientar a próxima revisão.</p><footer>Edilaine Francescato · Revisão ilustrativa de 5 de outubro</footer></section><section class="orientation-card">${badge('Canais e horários','blue','clock')}<h2>Como pedir retorno</h2><p>O acompanhamento real terá canais, horários e responsáveis acordados com a Francescato. Aqui, você vê como essas informações serão organizadas.</p><p>O diário não garante resposta imediata. Um envio, uma leitura e um retorno são situações diferentes.</p><footer>Exemplo de estrutura para validar com Edilaine.</footer></section><section class="orientation-card">${badge('A preencher com profissional habilitado','amber','lock')}<h2>Plano de crise do caso</h2><p>Este espaço apresentará as orientações aprovadas, os contatos e o fluxo acordado pela equipe. Não há orientação clínica ou plano de emergência real nesta demonstração.</p>${btn('Ver estrutura do plano','crisis','','soft','file')}</section>`;}

const tourSteps=[
 {title:'O dia da Edilaine',text:'Mostre o relato recente, a rede, a carteira e os próximos passos.',role:'manager',view:'inicio'},
 {title:'A família participa',text:'Use a transcrição de exemplo, revise o texto e publique o relato.',role:'family',view:'inicio',compose:'audio'},
 {title:'O relato chega à coordenação',text:'Dê um retorno ou transforme um registro em próximo passo.',role:'manager',view:'caso',tab:'diario'},
 {title:'O profissional compartilha a síntese',text:'Preencha o modelo e confira quem poderá ler antes de publicar.',role:'professional',view:'caso',tab:'diario',compose:'text'},
 {title:'O plano acompanha a vida real',text:'Revise um objetivo e mostre o responsável e a próxima revisão.',role:'manager',view:'caso',tab:'plano'},
 {title:'Uma agenda para o cuidado',text:'Abra um compromisso e demonstre o registro de realização.',role:'manager',view:'agenda'},
 {title:'Documentos e sugestões',text:'Veja um documento de exemplo e anote o que Edilaine gostaria de ajustar.',role:'manager',view:'caso',tab:'documentos'},
];
function render(){
 const p=profiles[state.role];if(!allowed(state.caseId))state.caseId=allowedCases()[0].id;
 const route=state.view==='caso'?casePage():state.view==='casos'?casesPage():state.view==='agenda'?agendaPage():state.view==='tarefas'?tasksPage():state.view==='equipe'?teamPage():state.view==='documentos'?documentsPage():state.view==='orientacoes'?orientationsPage():dashboard();
 const crumb=state.view==='caso'?esc(getCase().name):esc(navLabels[state.view]?.[1]||'Meu dia');
 const navActive=state.view==='caso'?(['family','patient'].includes(state.role)?state.tab==='resumo'?'inicio':state.tab:state.tab==='diario'&&state.role==='professional'?'diario':'casos'):state.view;
 $('#app').innerHTML=`<aside class="sidebar ${state.menu?'open':''}" aria-label="Navegação principal"><button type="button" class="brand" data-action="nav" data-view="inicio" aria-label="Francescapp, início"><svg class="brand-mark" viewBox="0 0 40 45" aria-hidden="true"><path d="M19 38V11m0 13C3 28 0 13 9 9c7-3 10 6 10 15Zm0-5C19 5 27 0 33 7c6 8-1 16-14 12Zm1 10c15-10 22-1 15 7-8 8-14 1-15-7Z" fill="none" stroke="currentColor" stroke-width="1.3"/></svg><span class="brand-name">francescato<span>family case management</span></span></button><p class="workspace-label">${state.role==='manager'?'Coordenação do cuidado':state.role==='professional'?'Meu acompanhamento':'Cuidado compartilhado'}</p><nav class="nav">${p.nav.map(v=>`<button type="button" class="nav-button ${navActive===v?'active':''}" data-action="nav" data-view="${v}" ${navActive===v?'aria-current="page"':''}>${icon(navLabels[v][0])}${navLabels[v][1]}${v==='tarefas'?`<span class="nav-count">${tasksFor().filter(t=>!t.done).length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><strong>O cuidado tem continuidade.</strong>Um espaço para conectar pessoas, acontecimentos e próximos passos.</div><button type="button" class="nav-button" data-action="guide">${icon('tour')}Roteiro da reunião</button><button type="button" class="nav-button" data-action="feedback">${icon('chat')}Anotar uma sugestão</button><button type="button" class="nav-button" data-action="reset">${icon('refresh')}Restaurar demonstração</button><div class="user-mini">${avatar(p.initials,p.color)}<span>${esc(p.name)}<small>${esc(p.title)}</small></span></div></div></aside><div class="workspace"><header class="topbar"><button type="button" class="icon-button mobile-menu" data-action="menu" aria-label="Abrir ou fechar menu" aria-expanded="${state.menu}">${icon('menu')}</button><div class="breadcrumbs">Francescapp &nbsp;/&nbsp; <strong>${crumb}</strong></div><div class="header-actions">${['manager','professional'].includes(state.role)?`<form class="search-wrap" data-form="global-search">${icon('search')}<label class="sr-only" for="global-search">Buscar pessoa acompanhada</label><input id="global-search" name="query" placeholder="Buscar pessoa…" autocomplete="off"></form>`:''}<span class="demo-badge"><span class="demo-dot"></span>Demo · dados fictícios</span><div class="profile-control">${avatar(p.initials,p.color)}<div><label for="profile">Perfil de demonstração</label><select id="profile" aria-label="Perfil de demonstração"><option value="manager" ${state.role==='manager'?'selected':''}>Edilaine</option><option value="professional" ${state.role==='professional'?'selected':''}>Profissional</option><option value="family" ${state.role==='family'?'selected':''}>Família</option><option value="patient" ${state.role==='patient'?'selected':''}>Paciente</option></select></div></div></div></header><main id="main" class="content" tabindex="-1">${route}</main></div>${state.tour!==null?`<aside class="tour-bar" aria-label="Roteiro da apresentação"><span class="tour-progress">${state.tour+1} / ${tourSteps.length}</span><div><strong>${tourSteps[state.tour].title}</strong><small>${tourSteps[state.tour].text}</small></div>${state.tour>0?`<button class="icon-button" data-action="tour-prev" aria-label="Etapa anterior">${icon('back')}</button>`:''}${btn(state.tour===tourSteps.length-1?'Concluir roteiro':'Próxima etapa','tour-next','','small')}<button class="icon-button" data-action="tour-close" aria-label="Fechar roteiro">${icon('close')}</button></aside>`:''}`;
 document.title=`${state.view==='caso'?getCase().name:navLabels[state.view]?.[1]||'Meu dia'} | Francescapp`;
}
function go(view,caseId,tab){if($('#dialog').open)closeModal();state.menu=false;state.view=view;if(caseId&&allowed(caseId))state.caseId=caseId;if(tab)state.tab=tab;state.diaryFilter='Todos';render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function changeRole(role){if(!profiles[role])return;state.role=role;state.caseId='helena';state.view='inicio';state.tab='resumo';state.diaryFilter='Todos';state.docProvider='Todos';state.caseFilter='Todos';state.caseSearch='';state.menu=false;render();window.scrollTo({top:0,behavior:'instant'});}
function modal(title,body){const d=$('#dialog');d.innerHTML=`<header class="dialog-header"><h2 id="dialog-title">${title}</h2><button type="button" class="icon-button" data-action="close-dialog" aria-label="Fechar janela">${icon('close')}</button></header><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();}
const closeModal=()=>$('#dialog').close();
function caseOptions(selected){return allowedCases().map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('');}
function field(label,name,value='',type='text',full=false){return `<div class="field ${full?'full':''}"><label for="field-${name}">${label}</label>${type==='textarea'?`<textarea id="field-${name}" name="${name}">${esc(value)}</textarea>`:`<input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}">`}</div>`;}
const formEnd=(submit='Salvar',hint='Ação demonstrativa, guardada apenas neste navegador.')=>`<p class="form-error" role="alert"></p><div class="form-footer"><small class="muted">${hint}</small><div class="row">${btn('Cancelar','close-dialog')}<button class="button primary" type="submit">${submit}</button></div></div>`;
function openComposer(mode='text'){
 const c=getCase(),p=profiles[state.role],draft=data.drafts[`${state.role}:${c.id}`]||{};composer={mode,attachment:draft.attachment||null};
 const professional=state.role==='professional',family=['family','patient'].includes(state.role);
 modal(professional?'Registrar síntese profissional':'Registrar no diário',`<p class="dialog-subtitle">${professional?'Seu registro ajuda a equipe a acompanhar os combinados. Compartilhe apenas as informações necessárias.':'Conte o que aconteceu e o que você gostaria de levar à coordenação do cuidado.'}</p><form data-form="record"><div class="form-grid"><div class="field"><label for="record-case">Pessoa acompanhada</label><select id="record-case" name="caseId">${caseOptions(c.id)}</select></div><div class="field"><label for="record-date">Quando aconteceu?</label><input id="record-date" name="date" type="date" value="${draft.date||TODAY}" required></div></div><div class="composer-type">${btn('Escrever','composer-mode','data-mode="text"',mode==='text'?'active':'','edit')}${btn('Áudio de exemplo','composer-mode','data-mode="audio"',mode==='audio'?'active':'','mic')}</div><div id="audio-block" ${mode!=='audio'?'hidden':''}><div class="audio-demo"><span class="doc-icon">${icon('mic')}</span><div><strong style="font-size:12px">Um relato, sem precisar digitar</strong><br><small class="muted">Transcrição demonstrativa, sem microfone.</small></div><div class="audio-wave" aria-hidden="true">${[8,17,26,12,30,22,14,25,10,19,28,13].map(h=>`<i style="height:${h}px"></i>`).join('')}</div></div>${btn('Carregar transcrição de exemplo','transcribe','','soft','mic')}<p class="fine-print" style="margin-bottom:14px">O texto é fictício e pode ser editado. Nenhum áudio é captado ou enviado.</p></div><div class="form-grid">${field('Título do registro','title',draft.title||'', 'text',true)}<div class="field full"><label for="record-text">${professional?'Síntese para compartilhar':'O que aconteceu?'}</label><textarea id="record-text" name="text" placeholder="${professional?'O que foi feito e o que a equipe precisa acompanhar?':'Descreva o acontecimento com as suas palavras.'}" required>${esc(draft.text||'')}</textarea></div><div class="field"><label for="record-category">Tipo de registro</label><select id="record-category" name="category">${(professional?['Síntese profissional','Revisão do plano','Orientação']:family?['Acontecimento','Conquista','Rotina','Dificuldade','Dúvida']:['Coordenação','Revisão do plano','Orientação','Acontecimento']).map(v=>`<option ${draft.category===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="record-audience">Quem poderá ler?</label><select id="record-audience" name="audience">${family?`<option value="own">Coordenação e ${state.role==='patient'?'você':'familiar autor'}</option>`:`<option value="team">Equipe do caso</option><option value="shared">Equipe, paciente e família autorizados</option>`}</select></div>${field(professional?'Orientação / próximo passo (opcional)':'Contexto / o que foi feito (opcional)','context',draft.context||'','textarea',true)}</div><div class="row wrap section-gap">${btn('Imagem de exemplo','attach-example','','small','image')}<label class="button small" for="record-file">${icon('file')}Escolher imagem<input class="sr-only" type="file" id="record-file" accept="image/*"></label></div><div id="attachment-preview">${attachmentPreview()}</div>${family?`<label class="row section-gap" style="font-size:12px"><input name="request" type="checkbox" ${draft.request?'checked':''}>Gostaria de um retorno da coordenação</label>`:''}<div class="info-box section-gap" style="margin-bottom:0">${icon('lock')}<span>Revise o texto e a audiência antes de publicar. Esta apresentação utiliza apenas dados fictícios.</span></div><p class="form-error" role="alert"></p><div class="form-footer">${btn('Guardar rascunho','save-draft','','small')}<div class="row">${btn('Cancelar','close-dialog')}<button type="submit" class="button primary">${icon('check')}Publicar registro</button></div></div></form>`);
}
function attachmentPreview(){if(!composer.attachment)return '';return `<div class="attachment-chip">${icon('image')}<span>${composer.attachment==='exemplo'?'Caminhada na praça • imagem de exemplo':esc(composer.attachment.name)}</span><button type="button" class="icon-button" data-action="remove-attachment" aria-label="Remover anexo">${icon('close')}</button></div>`;}
function taskModal(recordId=null){const record=data.records.find(r=>r.id===recordId);modal('Um próximo passo para o cuidado',`<p class="dialog-subtitle">Defina o combinado, quem ficou responsável e quando ele será revisto.${record?' Este passo ficará ligado ao registro “'+esc(record.title)+'”.':''}</p><form data-form="task" data-record="${recordId||''}"><div class="form-grid">${field('O que precisa acontecer?','title','','text',true)}<div class="field"><label for="task-case">Pessoa acompanhada</label><select id="task-case" name="caseId">${caseOptions(record?.caseId||getCase().id)}</select></div><div class="field"><label for="task-owner">Responsável</label><select id="task-owner" name="owner">${(state.role==='professional'?['Marina']:['Edilaine','Marina','Carolina','Rafael']).map(n=>`<option>${n}</option>`).join('')}</select></div>${field('Até quando?','date',TODAY,'date',true)}</div>${formEnd('Criar próximo passo')}</form>`);}
function eventModal(id){const event=accessible(data.events).find(e=>e.id===id);if(!event)return;const canEdit=['manager','professional'].includes(state.role);modal(esc(event.title),`<p class="dialog-subtitle">${esc(caseBy(event.caseId).name)} · ${esc(event.area)}</p>${badge(event.status,event.status==='Realizado'?'':event.status==='Faltou'?'amber':'blue')}<dl class="details-table"><dt>Quando</dt><dd>${fullDate(event.date)}, às ${esc(event.time)}</dd><dt>Duração</dt><dd>${event.duration} minutos</dd><dt>Profissional</dt><dd>${esc(event.professional)}</dd><dt>Local</dt><dd>${esc(event.location)}</dd><dt>Audiência</dt><dd>${esc(audienceLabel(event.audience))}</dd></dl>${canEdit?`<form data-form="event-status" data-id="${id}"><div class="form-grid"><div class="field"><label for="event-status">Situação do compromisso</label><select id="event-status" name="status">${['Agendado','Realizado','Faltou','Cancelado','Realização não confirmada'].map(v=>`<option ${v===event.status?'selected':''}>${v}</option>`).join('')}</select></div>${field('Observação / motivo (opcional)','reason',event.reason||'')}</div>${formEnd('Salvar situação')}</form>`:`<p class="fine-print">A equipe confirma a realização ou a remarcação do compromisso.</p><div class="dialog-buttons">${btn('Fechar','close-dialog','','primary')}</div>`}`);}
function newEventModal(caseId){if(!['manager','professional'].includes(state.role))return;modal('Novo compromisso',`<form data-form="event"><div class="form-grid">${field('Nome do compromisso','title','','text',true)}<div class="field"><label for="new-event-case">Pessoa acompanhada</label><select id="new-event-case" name="caseId">${caseOptions(caseId||getCase().id)}</select></div><div class="field"><label for="new-event-pro">Profissional</label><select id="new-event-pro" name="professional">${(state.role==='professional'?['Marina Lima']:['Edilaine Francescato','Marina Lima','Carolina Freitas','Rafael Costa']).map(n=>`<option>${n}</option>`).join('')}</select></div>${field('Data','date',TODAY,'date')}${field('Horário','time','10:00','time')}<div class="field"><label for="new-event-duration">Duração</label><select id="new-event-duration" name="duration"><option value="30">30 minutos</option><option value="60" selected>60 minutos</option><option value="90">90 minutos</option></select></div><div class="field"><label for="new-event-location">Local / modalidade</label><select id="new-event-location" name="location"><option>Online</option><option>Presencial</option><option>Consultório</option></select></div><div class="field full"><label for="new-event-audience">Quem pode consultar?</label><select id="new-event-audience" name="audience"><option value="team">Equipe do caso</option><option value="shared">Equipe, paciente e família autorizados</option></select></div></div>${formEnd('Adicionar à agenda')}</form>`);}
function goalModal(id){if(state.role!=='manager')return;const g=data.goals.find(x=>x.id===id);if(g&&!allowed(g.caseId))return;modal(g?'Revisar objetivo':'Um objetivo que faz sentido',`<p class="dialog-subtitle">Registre uma escolha da pessoa e combine como acompanhar os próximos passos.</p><form data-form="goal" data-id="${id||''}"><div class="form-grid">${field('Objetivo','title',g?.title||'','text',true)}${field('Responsável','owner',g?.owner||'Edilaine e Helena')}<div class="field"><label for="goal-status">Situação</label><select id="goal-status" name="status">${['Em andamento','Atingido','Pausado','Revisar','Encerrado'].map(v=>`<option ${g?.status===v?'selected':''}>${v}</option>`).join('')}</select></div>${field('Próxima revisão','review',g?.review||'2026-10-09','date')}<div class="field"><label for="goal-progress">Progresso ilustrativo do combinado</label><select id="goal-progress" name="progress">${[0,20,25,35,40,50,70,100].map(n=>`<option value="${n}" ${g?.progress===n?'selected':''}>${n}%</option>`).join('')}</select></div>${field('O que mudou / como observar o progresso','note',g?.note||'','textarea',true)}</div>${formEnd(g?'Salvar revisão':'Adicionar objetivo')}</form>`);}
function newCaseModal(){if(state.role!=='manager')return;modal('Começar um acompanhamento',`<p class="dialog-subtitle">Cadastre uma pessoa fictícia para explorar a entrada no cuidado. O contexto pode ser preenchido aos poucos.</p><form data-form="case"><div class="form-grid">${field('Nome de exemplo','name','','text',true)}${field('Idade','age','30','number')}${field('Familiar / cuidador de referência','family','')}${field('Foco do acompanhamento','context','','text',true)}${field('O que a pessoa deseja','preference','','textarea',true)}</div>${formEnd('Criar caso de exemplo')}</form>`);}
function documentModal(id){const d=accessible(data.documents).find(x=>x.id===id);if(!d)return;const c=caseBy(d.caseId);modal(esc(d.name),`<p class="dialog-subtitle">Documento ilustrativo. Nenhum arquivo foi aberto no ${esc(d.provider)}.</p>${badge(d.type,'neutral')}<div class="form-section"><h3>${esc(c.name)}</h3><p style="font-size:13px">${esc(['family','patient'].includes(state.role)?c.familySummary:c.summary)}</p><h3 style="margin-top:20px">Objetivos e próximos passos</h3><p style="font-size:12px;color:var(--muted)">${data.goals.filter(g=>g.caseId===c.id).map(g=>esc(g.title)).join('<br>')}</p></div><dl class="details-table"><dt>Origem</dt><dd>${esc(d.author)}</dd><dt>Data</dt><dd>${fullDate(d.date)}</dd><dt>Espaço</dt><dd>${esc(d.provider)} • demonstração</dd><dt>Acesso</dt><dd>${esc(audienceLabel(d.audience))}</dd></dl><div class="dialog-buttons">${btn('Baixar resumo de exemplo','export-doc',`data-id="${id}"`,'primary','download')}</div>`);}
function newDocModal(caseId){if(state.role!=='manager')return;modal('Adicionar documento de exemplo',`<p class="dialog-subtitle">Inclua a identificação de um documento fictício. Esta ação não envia arquivos para um provedor.</p><form data-form="document"><div class="form-grid">${field('Nome do documento','name','','text',true)}<div class="field"><label for="document-case">Pessoa acompanhada</label><select id="document-case" name="caseId">${caseOptions(caseId||getCase().id)}</select></div><div class="field"><label for="document-provider">Espaço institucional</label><select id="document-provider" name="provider"><option>Google Drive</option><option>OneDrive</option></select></div><div class="field"><label for="document-type">Categoria</label><select id="document-type" name="type"><option>Relatório</option><option>Plano</option><option>Orientação</option><option>Termo</option></select></div><div class="field"><label for="document-audience">Audiência</label><select id="document-audience" name="audience"><option value="team">Equipe do caso</option><option value="shared">Equipe, paciente e família autorizados</option></select></div></div>${formEnd('Adicionar exemplo')}</form>`);}
const newDocModalBase=newDocModal;
newDocModal=function(caseId){
 if(!['manager','professional'].includes(state.role))return;
 modal('Adicionar anexo ao caso',`<p class="dialog-subtitle">Classifique o anexo antes de guardá-lo na pasta institucional da pessoa acompanhada.</p><form data-form="document"><div class="form-grid"><div class="field full"><label for="document-file">Arquivo</label><input id="document-file" name="file" type="file" aria-describedby="document-file-note"><small id="document-file-note">Demonstração: o arquivo não será enviado nesta tela.</small></div>${field('Nome para exibir','name','','text',true)}<div class="field"><label for="document-case">Pessoa acompanhada</label><select id="document-case" name="caseId">${caseOptions(caseId||getCase().id)}</select></div><div class="field"><label for="document-type">Classificação</label><select id="document-type" name="type"><option>Laudo</option><option>Exame</option><option>Relatório</option><option>Plano</option><option>Orientação</option><option>Termo</option><option>Imagem</option><option>Outro</option></select></div><div class="field full"><label for="document-audience">Quem poderá consultar?</label><select id="document-audience" name="audience"><option value="team">Equipe do caso</option><option value="shared">Equipe, paciente e família autorizados</option></select></div></div><div class="info-box section-gap" style="margin-bottom:0">${icon('cloud')}<span>Destino proposto: Google Drive institucional da Francescato, na pasta do caso selecionado.</span></div>${formEnd('Classificar e adicionar','O mockup demonstra a organização; nenhuma conta ou arquivo real é acessado.')}</form>`);
};
function feedbackModal(){modal('O que podemos ajustar?',`<p class="dialog-subtitle">Registre ideias durante a conversa com Edilaine. Use apenas sugestões de produto, sem dados de pacientes.</p><form data-form="feedback"><div class="form-grid">${field('Sugestão ou necessidade','text','','textarea',true)}<div class="field full"><label for="feedback-area">Em qual parte?</label><select id="feedback-area" name="area">${['Diário','Visão da case manager','Visão profissional','Família e paciente','Agenda','Plano de cuidado','Permissões','Documentos','Outra ideia'].map(a=>`<option>${a}</option>`).join('')}</select></div></div>${formEnd('Guardar sugestão','Ideias ficam neste navegador e podem ser baixadas.')}</form>${data.notes.length?`<div class="section-gap"><div class="section-header"><h3>Ideias desta conversa</h3>${btn('Baixar anotações','export-notes','','small','download')}</div>${data.notes.map(n=>`<article class="feedback-card"><p>${esc(n.text)}</p><small>${esc(n.area)} · ${esc(n.profile)}</small></article>`).join('')}</div>`:''}`);}
function guideModal(){modal('Uma demonstração em 7 momentos',`<p class="dialog-subtitle">Comece pelo dia da Edilaine e conte a história de um registro que vira cuidado compartilhado. Navegue livremente ou use o roteiro guiado.</p><div class="guide-grid">${tourSteps.map((s,i)=>`<button type="button" class="guide-item" data-action="tour-start" data-step="${i}"><strong>${i+1}. ${s.title}</strong><small>${s.text}</small></button>`).join('')}</div><div class="dialog-buttons">${btn('Começar a apresentação','tour-start','data-step="0"','primary','tour')}</div>`);}
function goTour(step){if($('#dialog').open)closeModal();if(step>=tourSteps.length){state.tour=null;render();toast('Roteiro concluído. Use “Anotar uma sugestão” para registrar as ideias.');return;}state.tour=Math.max(0,step);const s=tourSteps[state.tour];changeRole(s.role);state.caseId='helena';state.view=s.view;state.tab=s.tab||'resumo';render();window.scrollTo({top:0,behavior:'instant'});if(s.compose)openComposer(s.compose);}
function downloadText(name,text){const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function rejectForm(form,message){const area=$('.form-error',form);if(area)area.textContent=message;}
function finish(message){persist();closeModal();render();toast(message);}

document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el)return;
 const {action,id,view,tab,mode,filter,provider}=el.dataset;
 if(action==='nav'){if(!profiles[state.role].nav.includes(view))return;if(['diario','plano'].includes(view))go('caso',getCase().id,view);else go(view);}
 if(action==='case'){if(allowed(id))go('caso',id,el.dataset.tab||'resumo');}
 if(action==='case-tab')go('caso',getCase().id,tab);
 if(action==='compose')openComposer(mode||'text');
 if(action==='close-dialog')closeModal();
 if(action==='menu'){state.menu=!state.menu;render();}
 if(action==='case-filter'){state.caseFilter=filter;render();}
 if(action==='diary-filter'){state.diaryFilter=filter;render();}
 if(action==='task-filter'){state.taskFilter=filter;render();}
 if(action==='doc-provider'){state.docProvider=provider;render();}
 if(action==='agenda-mode'){state.agendaMode=mode;render();}
 if(action==='calendar-sync'){toast('Agenda atualizada com o Google Agenda na demonstração.');}
 if(action==='week-prev'){state.week--;render();}
 if(action==='week-next'){state.week++;render();}
 if(action==='week-reset'){state.week=0;render();}
 if(action==='task-toggle'){const t=tasksFor().find(x=>x.id===id);if(!t)return;t.done=!t.done;persist();render();toast(t.done?'Próximo passo concluído.':'Próximo passo reaberto.');}
 if(action==='new-task')taskModal();
 if(action==='record-task'){if(state.role==='manager')taskModal(id);}
 if(action==='event')eventModal(id);
 if(action==='new-event')newEventModal(el.dataset.case);
 if(action==='new-case')newCaseModal();
 if(action==='goal')goalModal(id);
 if(action==='new-goal')goalModal();
 if(action==='prepare-summary'){
   if(state.role!=='manager'||!allowed(el.dataset.case))return;const c=caseBy(el.dataset.case),recent=recordsFor(c.id).slice(0,3);const draft=recent.map(r=>`${r.author}: ${r.title}. ${r.text}`).join('\n\n');
   modal('Preparar a próxima revisão',`<p class="dialog-subtitle">Um rascunho reúne os registros recentes autorizados para você. A síntese só será atualizada depois da sua revisão.</p><div class="info-box">${icon('info')}<span>Reunião de trechos demonstrativa, feita neste navegador. Não há serviço de inteligência artificial conectado.</span></div><form data-form="summary" data-case="${c.id}">${field('Síntese a revisar','text',draft||c.summary,'textarea',true)}<div class="form-section"><h3>Registros de origem</h3>${recent.map(r=>`<p class="goal-note">${esc(r.author)} · ${datestr(r.date)}<br><strong>${esc(r.title)}</strong></p>`).join('')}</div>${formEnd('Confirmar revisão','A síntese continua na audiência da coordenação.')}</form>`);
 }
 if(action==='document')documentModal(id);
 if(action==='new-doc')newDocModal(el.dataset.case);
 if(action==='composer-mode'){composer.mode=mode;$('#audio-block').hidden=mode!=='audio';document.querySelectorAll('[data-action="composer-mode"]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));}
 if(action==='transcribe'){
   $('#record-text').value=state.role==='professional'?'No encontro de hoje, revisamos as atividades que Helena gostaria de retomar. Ela contou que a caminhada foi um momento agradável. Combinamos registrar o que ajudou na rotina e levar essas observações à revisão de sexta-feira.':state.role==='patient'?'Hoje eu consegui sair para uma caminhada curta depois do café. Gostei de estar na praça e gostaria de combinar outro momento nesta semana. Quero conversar sobre o que me ajudou a começar o dia.':'Hoje a Helena tomou café conosco e sugeriu uma caminhada na praça. Fomos sem pressa e ela disse que gostaria de repetir. Gostaria de levar essa conquista à próxima conversa com a equipe.';
   $('#field-title').value=state.role==='professional'?'Síntese do encontro de hoje':'Um momento importante na rotina';
   el.innerHTML=icon('check')+'Transcrição de exemplo carregada';toast('Rascunho de exemplo carregado. Revise antes de publicar.');
 }
 if(action==='attach-example'){composer.attachment='exemplo';$('#attachment-preview').innerHTML=attachmentPreview();}
 if(action==='remove-attachment'){composer.attachment=null;$('#attachment-preview').innerHTML='';$('#record-file').value='';}
 if(action==='save-draft'){const form=$('form[data-form="record"]');const f=Object.fromEntries(new FormData(form));data.drafts[`${state.role}:${f.caseId}`]={...f,attachment:composer.attachment,request:!!f.request};persist();closeModal();toast('Rascunho guardado para este perfil e caso.');}
 if(action==='reply'){const r=accessible(data.records).find(r=>r.id===id);if(!r||state.role!=='manager')return;modal('Retorno ao registro',`<p class="dialog-subtitle">${esc(r.title)}<br>Autor: ${esc(r.author)}</p><form data-form="reply" data-id="${id}">${field('O que você gostaria de devolver ao autor?','text',r.reply||'Obrigada por compartilhar. Vou levar essa observação à próxima revisão e combinar os próximos passos com a equipe.','textarea',true)}${formEnd('Registrar retorno','O retorno segue a audiência do registro.')}</form>`);}
 if(action==='share-record'){const r=accessible(data.records).find(r=>r.id===id);if(!r||state.role!=='manager')return;modal('Compartilhar com a equipe do caso',`<p class="dialog-subtitle">Você está ampliando a audiência do registro “${esc(r.title)}”.</p><div class="info-box">${icon('lock')}<span>Na operação real, a finalidade e a autorização aplicável precisam ser conferidas. Aqui, a mudança demonstra como a audiência fica visível.</span></div><p style="font-size:13px">O profissional vinculado ao caso poderá ler este relato. Outros familiares não recebem acesso por esta ação.</p><div class="dialog-buttons">${btn('Cancelar','close-dialog')}${btn('Confirmar na demonstração','confirm-share',`data-id="${id}"`,'primary','share')}</div>`);}
 if(action==='confirm-share'){const r=data.records.find(r=>r.id===id);if(r&&state.role==='manager'&&allowed(r.caseId)){if(!r.audience.includes('professional'))r.audience.push('professional');finish('Registro compartilhado com a equipe na demonstração.');}}
 if(action==='attachment'){const r=accessible(data.records).find(r=>r.id===id);if(!r)return;modal('Imagem do registro',`<p class="dialog-subtitle">${esc(r.title)} · ${esc(r.author)}</p>${r.attachment==='exemplo'?`<svg viewBox="0 0 520 290" role="img" aria-label="Ilustração de exemplo de uma caminhada em uma praça" style="width:100%;border-radius:12px"><rect width="520" height="290" fill="#eef2e7"/><path d="M0 231Q130 149 272 232T520 230V290H0Z" fill="#d4ddb9"/><path d="M175 290Q250 161 520 248" stroke="#e3ccb0" stroke-width="36" fill="none"/><path d="M75 229V95m0 57C7 149 19 73 75 70c69 2 64 82 0 82Zm371 80V85m0 57c-75 0-69-89 0-87 62 3 76 82 0 87Z" stroke="#879257" fill="#aeba7b" stroke-width="4"/><circle cx="257" cy="180" r="14" fill="#6f604b"/><path d="m256 201-13 36m13-36 18 34m-20-24-20 6m24-17 20 13" stroke="#475436" stroke-width="8" stroke-linecap="round"/><text x="24" y="270" fill="#475436" font-family="Raleway,Arial" font-size="12">Imagem ilustrativa. Não é fotografia de paciente.</text></svg>`:`<p style="font-size:13px">${esc(r.attachment.name||r.attachment)}</p><p class="fine-print">O mockup guarda a identificação do anexo, sem enviar ou conservar o conteúdo do arquivo.</p>`}<div class="dialog-buttons">${btn('Fechar','close-dialog','','primary')}</div>`);}
 if(action==='team-detail'){const member=team.find(t=>t.id===id);if(!member)return;const cases=allowedCases().filter(c=>id==='edilaine'||c.professionals.includes(id));modal(esc(member.name),`<div class="row">${avatar(member.initials,member.color,'big')}<div><h3>${esc(member.area)}</h3><small class="muted">${esc(member.frequency)}</small></div></div><div class="form-section"><h3>Participação no cuidado</h3><p class="goal-note">${esc(member.responsibility)}</p><div class="case-list section-gap">${caseRows(cases)}</div></div><p class="fine-print">Equipe e vínculos fictícios para demonstrar a experiência. Contatos reais não estão incluídos.</p>`);}
 if(action==='crisis')modal('Estrutura do plano de crise',`<p class="dialog-subtitle">Modelo de organização para validar com a equipe. Não contém orientação clínica real.</p><div class="facts"><div class="fact"><small>Profissional que aprova</small><p>Identificação e data da revisão.</p></div><div class="fact"><small>Orientações acordadas</small><p>Conteúdo específico aprovado para o caso.</p></div><div class="fact"><small>Contatos e disponibilidade</small><p>Canais, horários e responsáveis.</p></div><div class="fact"><small>Limites do diário</small><p>Envio de registro não garante resposta imediata.</p></div></div><div class="dialog-buttons">${btn('Fechar','close-dialog','','primary')}</div>`);
 if(action==='export-doc'){const d=accessible(data.documents).find(x=>x.id===id);if(!d)return;const c=caseBy(d.caseId);downloadText('francescapp-resumo-exemplo.txt',`FRANCESCAPP - DOCUMENTO FICTÍCIO\n\n${d.name}\n${c.name}\nOrigem: ${d.author}\n\n${['family','patient'].includes(state.role)?c.familySummary:c.summary}\n\nOBJETIVOS\n${data.goals.filter(g=>g.caseId===c.id).map(g=>'- '+g.title).join('\n')}\n\nApenas para apresentação. Sem dados reais ou conexão a serviços.`);toast('Resumo fictício baixado.');}
 if(action==='feedback')feedbackModal();
 if(action==='export-notes'){downloadText('francescapp-sugestoes-reuniao.txt',`IDEIAS PARA O FRANCESCAPP\n\n${data.notes.map((n,i)=>`${i+1}. ${n.area}\n${n.text}\nVisão: ${n.profile}`).join('\n\n')}`);toast('Anotações baixadas.');}
 if(action==='guide')guideModal();
 if(action==='tour-start'){closeModal();goTour(Number(el.dataset.step));}
 if(action==='tour-next')goTour(state.tour+1);
 if(action==='tour-prev')goTour(state.tour-1);
 if(action==='tour-close'){state.tour=null;render();}
 if(action==='reset')modal('Restaurar os exemplos?',`<p class="dialog-subtitle">Isso remove os registros, tarefas e sugestões adicionados nesta demonstração e volta aos exemplos iniciais. Baixe as anotações antes, se quiser guardá-las.</p><div class="dialog-buttons">${data.notes.length?btn('Baixar anotações','export-notes','','small','download'):''}${btn('Cancelar','close-dialog')}${btn('Restaurar exemplos','confirm-reset','','primary','refresh')}</div>`);
 if(action==='confirm-reset'){data=structuredClone(seed);persist();closeModal();state.tour=null;changeRole('manager');toast('Demonstração restaurada.');}
});

document.addEventListener('change',event=>{
 if(event.target.id==='profile')changeRole(event.target.value);
 if(event.target.id==='record-file'){const file=event.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Escolha uma imagem para este exemplo.');event.target.value='';return;}composer.attachment={name:file.name};$('#attachment-preview').innerHTML=attachmentPreview();toast('Imagem selecionada. Apenas o nome será guardado no mockup.');}
 if(event.target.id==='record-case'){const f=event.target.closest('form'),draft=data.drafts[`${state.role}:${event.target.value}`]||{};$('#field-title',f).value=draft.title||'';$('#record-text',f).value=draft.text||'';$('#field-context',f).value=draft.context||'';composer.attachment=draft.attachment||null;$('#attachment-preview').innerHTML=attachmentPreview();}
});
document.addEventListener('input',event=>{if(event.target.id==='case-search'){state.caseSearch=event.target.value;$('#case-grid').innerHTML=caseTiles(filteredCases());}});
document.addEventListener('submit',event=>{
 const form=event.target;if(!form.dataset.form)return;event.preventDefault();const f=Object.fromEntries(new FormData(form));
 if(form.dataset.form==='global-search'){state.caseSearch=f.query.trim();state.caseFilter='Todos';go('casos');return;}
 if(form.dataset.form==='record'){
   if(!allowed(f.caseId))return;if(!f.text.trim())return rejectForm(form,'Descreva o acontecimento ou a síntese antes de publicar.');if(!f.date)return rejectForm(form,'Informe quando aconteceu.');
   const p=profiles[state.role],audience=['manager'];if(['family','patient'].includes(state.role))audience.push(state.role);else audience.push('professional');if(f.audience==='shared')audience.push('family','patient');
   const date=new Date();data.records.push({id:'r'+Date.now(),caseId:f.caseId,author:p.name,initials:p.initials,role:state.role,category:f.category,title:f.title.trim()||f.category,text:f.text.trim(),context:f.context.trim(),date:f.date,time:`${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`,audience,status:f.request?'Aguardando retorno':state.role==='family'||state.role==='patient'?'Enviado à coordenação':'Compartilhado com a equipe',attachment:composer.attachment,request:!!f.request});
   delete data.drafts[`${state.role}:${f.caseId}`];const c=caseBy(f.caseId);c.summaryReviewed=false;c.last='Atualizado na demonstração';if(['family','patient'].includes(state.role)){c.status='Novo relato';c.statusKind='amber';c.change=`${p.short} adicionou um registro na demonstração.`;}
   persist();closeModal();go('caso',f.caseId,'diario');toast('Registro publicado na demonstração.');return;
 }
 if(form.dataset.form==='task'){
   if(!['manager','professional'].includes(state.role)||!allowed(f.caseId))return;if(!f.title.trim()||!f.date)return rejectForm(form,'Informe a ação e a data de acompanhamento.');
   const record=data.records.find(r=>r.id===form.dataset.record);if(record&&record.caseId!==f.caseId)return rejectForm(form,'O próximo passo ligado a um registro deve permanecer no mesmo caso.');
   data.tasks.push({id:'t'+Date.now(),caseId:f.caseId,title:f.title.trim(),owner:state.role==='professional'?'Marina':f.owner,date:f.date,done:false,recordId:form.dataset.record||null});finish('Próximo passo criado.');return;
 }
 if(form.dataset.form==='reply'){
   const r=data.records.find(r=>r.id===form.dataset.id);if(state.role!=='manager'||!r||!allowed(r.caseId))return;if(!f.text.trim())return rejectForm(form,'Escreva o retorno antes de confirmar.');r.reply=f.text.trim();r.status='Retorno registrado';r.request=false;const c=caseBy(r.caseId);if(!data.records.some(x=>x.caseId===c.id&&x.request)){c.status='Acompanhado';c.statusKind='';}finish('Retorno registrado e visível ao autor.');return;
 }
 if(form.dataset.form==='event-status'){
   const e=accessible(data.events).find(e=>e.id===form.dataset.id);if(!e||!['manager','professional'].includes(state.role))return;e.status=f.status;e.reason=f.reason;finish('Situação do compromisso atualizada.');return;
 }
 if(form.dataset.form==='event'){
   if(!['manager','professional'].includes(state.role)||!allowed(f.caseId))return;if(!f.title.trim()||!f.date||!f.time)return rejectForm(form,'Informe o compromisso, a data e o horário.');
   const [hour,minute]=f.time.split(':').map(Number);if(hour<8||hour+minute/60+Number(f.duration)/60>17)return rejectForm(form,'Para a grade deste mockup, o compromisso deve começar e terminar entre 08:00 e 17:00.');
   const weekday=new Date(f.date+'T12:00:00').getDay();if(weekday===0||weekday===6)return rejectForm(form,'Esta agenda demonstrativa apresenta dias úteis. Escolha de segunda a sexta.');
   const audience=['manager',...(state.role==='professional'||f.professional==='Marina Lima'?['professional']:[])];if(f.audience==='shared')audience.push('family','patient');
   data.events.push({id:'e'+Date.now(),caseId:f.caseId,title:f.title.trim(),professional:state.role==='professional'?'Marina Lima':f.professional,area:'Compromisso do cuidado',date:f.date,time:f.time,duration:Number(f.duration),location:f.location,audience,color:'',status:'Agendado'});
   const target=new Date(f.date+'T12:00:00'),base=new Date('2026-10-05T12:00:00');state.week=Math.floor((target-base)/604800000);state.agendaMode='semana';persist();closeModal();go('agenda');toast('Compromisso adicionado à agenda.');return;
 }
 if(form.dataset.form==='goal'){
   if(state.role!=='manager')return;if(!f.title.trim()||!f.owner.trim()||!f.review||!f.note.trim())return rejectForm(form,'Informe o objetivo, o responsável, a revisão e como observar o progresso.');
   const goal=data.goals.find(g=>g.id===form.dataset.id);const values={title:f.title.trim(),owner:f.owner.trim(),review:f.review,note:f.note.trim(),status:f.status,progress:f.status==='Atingido'?100:Number(f.progress)};
   if(goal){if(!allowed(goal.caseId))return;goal.history=[...(goal.history||[]),{title:goal.title,note:goal.note,status:goal.status,date:TODAY}];Object.assign(goal,values);}else data.goals.push({id:'g'+Date.now(),caseId:getCase().id,area:'Cuidado compartilhado',...values});finish('Objetivo atualizado na demonstração.');return;
 }
 if(form.dataset.form==='case'){
   if(state.role!=='manager')return;if(!f.name.trim()||!f.context.trim())return rejectForm(form,'Informe um nome fictício e o foco do acompanhamento.');const age=Number(f.age);if(!Number.isInteger(age)||age<0||age>120)return rejectForm(form,'Informe uma idade de exemplo entre 0 e 120.');
   const id='caso'+Date.now();data.cases.push({id,name:f.name.trim(),initials:f.name.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase(),age,color:'sand',status:'Contexto a preencher',statusKind:'neutral',context:f.context.trim(),change:'Um novo acompanhamento começa pelo contexto da pessoa.',review:'A combinar',family:f.family.trim()||'A identificar',preference:f.preference.trim()||'A combinar com a pessoa',summary:'O acompanhamento está começando. O contexto e os objetivos serão combinados com a pessoa e a equipe.',familySummary:'Acompanhamento em preparação.',strength:'A conhecer',barrier:'A conhecer',last:'Criado na demonstração',professionals:[]});persist();closeModal();go('caso',id,'anamnese');toast('Caso fictício criado.');return;
 }
 if(form.dataset.form==='document'){
   if(!['manager','professional'].includes(state.role)||!allowed(f.caseId))return;const filename=f.file&&f.file.name?f.file.name:'';const name=(f.name||'').trim()||filename;if(!name)return rejectForm(form,'Escolha um arquivo ou informe o nome do anexo.');const audience=['manager','professional'];if(f.audience==='shared')audience.push('family','patient');data.documents.push({id:'d'+Date.now(),caseId:f.caseId,name,type:f.type,date:TODAY,author:profiles[state.role].name,provider:'Google Drive',audience});state.docProvider='Todos';finish('Anexo classificado e organizado no Google Drive (demonstração).');return;
 }
 if(form.dataset.form==='anamnese'){
   if(state.role!=='manager'||!allowed(form.dataset.case))return;const c=caseBy(form.dataset.case);data.anamneses[c.id]={...f,saved:true};c.preference=f.preference;c.strength=f.strength;c.barrier=f.barrier;persist();render();toast('Contexto atualizado na demonstração.');return;
 }
 if(form.dataset.form==='summary'){
   if(state.role!=='manager'||!allowed(form.dataset.case))return;if(!f.text.trim())return rejectForm(form,'Revise a síntese antes de confirmar.');const c=caseBy(form.dataset.case);c.summaryHistory=[...(c.summaryHistory||[]),c.coordinationSummary||c.summary];c.coordinationSummary=f.text.trim();c.summaryReviewed=true;finish('Síntese revisada e atualizada na demonstração.');return;
 }
 if(form.dataset.form==='feedback'){
   if(!f.text.trim())return rejectForm(form,'Descreva a ideia que você quer guardar.');data.notes.push({text:f.text.trim(),area:f.area,profile:profiles[state.role].title});persist();feedbackModal();toast('Sugestão guardada para a reunião.');return;
 }
});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const bounds=$('#dialog').getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)closeModal();}});
render();
